import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import ChangelogFilteredList from '@/components/changelog/ChangelogFilteredList';

const mockReplace = jest.fn();
const mockPush = jest.fn();
let currentParams = new URLSearchParams();

jest.mock('next/navigation', () => ({
  useSearchParams: () => currentParams,
  useRouter: () => ({ replace: mockReplace, push: mockPush }),
  usePathname: () => '/changelog',
}));

const entries = [
  { id: 'a', title: 'Firebase logon shipped', description: 'auth work', date: '2025-01-15' },
  { id: 'b', title: 'Legacy migration completed', description: 'migration', date: '2024-06-01' },
  { id: 'c', title: 'Payment retry logic', description: 'retry', date: '2025-03-12' },
  { id: 'd', title: 'Statement layout tweak', description: 'copy', date: '2024-09-09' },
];

function setParams(qs: string) {
  currentParams = new URLSearchParams(qs);
}

beforeEach(() => {
  mockReplace.mockClear();
  mockPush.mockClear();
  setParams('');
});

describe('URL-backed changelog filters', () => {
  it('AC1: ?year=2024 shows only 2024 entries on load', () => {
    setParams('year=2024');
    render(<ChangelogFilteredList entries={entries} />);
    expect(screen.getByText('Legacy migration completed')).toBeInTheDocument();
    expect(screen.getByText('Statement layout tweak')).toBeInTheDocument();
    expect(screen.queryByText('Firebase logon shipped')).not.toBeInTheDocument();
    expect(screen.queryByText('Payment retry logic')).not.toBeInTheDocument();
  });

  it('AC2: ?q=FIREBASE matches case-insensitively; input shows the raw value', () => {
    setParams('q=FIREBASE');
    render(<ChangelogFilteredList entries={entries} />);
    const search = screen.getByRole('searchbox');
    expect(search).toHaveValue('FIREBASE');
    expect(screen.getByText('Firebase logon shipped')).toBeInTheDocument();
    expect(screen.queryByText('Legacy migration completed')).not.toBeInTheDocument();
  });

  it('AC3: ?year=2025&q=retry combines both filters', () => {
    setParams('year=2025&q=retry');
    render(<ChangelogFilteredList entries={entries} />);
    expect(screen.getByText('Payment retry logic')).toBeInTheDocument();
    expect(screen.queryByText('Firebase logon shipped')).not.toBeInTheDocument();
    expect(screen.queryByText('Legacy migration completed')).not.toBeInTheDocument();
    expect(screen.queryByText('Statement layout tweak')).not.toBeInTheDocument();
  });

  it('AC4: ?q= (empty) renders all entries', () => {
    setParams('q=');
    render(<ChangelogFilteredList entries={entries} />);
    expect(screen.getByText('Firebase logon shipped')).toBeInTheDocument();
    expect(screen.getByText('Legacy migration completed')).toBeInTheDocument();
    expect(screen.getByText('Payment retry logic')).toBeInTheDocument();
    expect(screen.getByText('Statement layout tweak')).toBeInTheDocument();
  });

  it('AC5: ?q= with only whitespace renders all entries', () => {
    setParams('q=%20%20%20');
    render(<ChangelogFilteredList entries={entries} />);
    expect(screen.getByText('Firebase logon shipped')).toBeInTheDocument();
    expect(screen.getByText('Legacy migration completed')).toBeInTheDocument();
  });

  it('AC6: ?year=notayear is ignored and all entries render', () => {
    setParams('year=notayear');
    render(<ChangelogFilteredList entries={entries} />);
    expect(screen.getByText('Firebase logon shipped')).toBeInTheDocument();
    expect(screen.getByText('Legacy migration completed')).toBeInTheDocument();
    expect(screen.getByText('Statement layout tweak')).toBeInTheDocument();
  });

  it('AC7: ?year=1999 (unknown numeric year) is ignored and all entries render', () => {
    setParams('year=1999');
    render(<ChangelogFilteredList entries={entries} />);
    expect(screen.getByText('Firebase logon shipped')).toBeInTheDocument();
    expect(screen.getByText('Legacy migration completed')).toBeInTheDocument();
  });

  it('AC8: selecting a year calls router.replace (not push) with ?year=', async () => {
    render(<ChangelogFilteredList entries={entries} />);
    await userEvent.selectOptions(screen.getByRole('combobox', { name: /year/i }), '2025');
    expect(mockReplace).toHaveBeenCalled();
    expect(mockPush).not.toHaveBeenCalled();
    const [call] = mockReplace.mock.calls.at(-1)!;
    expect(call).toMatch(/\/changelog\?year=2025/);
  });

  it('AC9: typing in the search box calls router.replace (not push) on each keystroke', async () => {
    render(<ChangelogFilteredList entries={entries} />);
    await userEvent.type(screen.getByRole('searchbox'), 'fire');
    expect(mockReplace).toHaveBeenCalled();
    expect(mockPush).not.toHaveBeenCalled();
    const finalUrl = mockReplace.mock.calls.at(-1)![0];
    expect(finalUrl).toMatch(/\/changelog\?q=fire/);
  });

  it('AC10: clearing the year filter removes ?year rather than leaving ?year=', async () => {
    setParams('year=2025');
    render(<ChangelogFilteredList entries={entries} />);
    await userEvent.selectOptions(screen.getByRole('combobox', { name: /year/i }), '');
    const finalUrl = mockReplace.mock.calls.at(-1)![0];
    expect(finalUrl).not.toMatch(/year=/);
  });

  it('AC11: clearing the search input removes ?q rather than leaving ?q=', async () => {
    setParams('q=firebase');
    render(<ChangelogFilteredList entries={entries} />);
    const search = screen.getByRole('searchbox');
    await userEvent.clear(search);
    const finalUrl = mockReplace.mock.calls.at(-1)![0];
    expect(finalUrl).not.toMatch(/q=/);
  });

  it('AC12: a filter that matches nothing renders an empty region, not the full list', () => {
    setParams('q=xyznotamatchxyz');
    render(<ChangelogFilteredList entries={entries} />);
    expect(screen.queryByText('Firebase logon shipped')).not.toBeInTheDocument();
    expect(screen.queryByText('Legacy migration completed')).not.toBeInTheDocument();
    expect(screen.queryByText('Payment retry logic')).not.toBeInTheDocument();
    expect(screen.queryByText('Statement layout tweak')).not.toBeInTheDocument();
  });
});

import { GET } from '@/app/changelog.xml/route';

function req(url: string) {
  return new Request(url);
}

describe('RSS feed is unaffected by /changelog filter parameters', () => {
  it('AC13: response body is identical whether ?year and ?q are present or absent', async () => {
    const plain = await GET(req('http://localhost/changelog.xml'));
    const withParams = await GET(req('http://localhost/changelog.xml?year=2025&q=firebase'));
    const plainBody = await plain.text();
    const withParamsBody = await withParams.text();
    expect(withParamsBody).toBe(plainBody);
  });
});
